with cleaned as (select *, case when quantity >= 197 then 'High' when quantity >= 84 then 'Medium' else 'Low' end quantity_tier from inventory where last_restock > date '2023-02-28'), with_windows as (select *, row_number() over (partition by product_id, store_id order by last_restock desc, id asc) row_seq, ntile(4) over (partition by date_trunc('WEEK', last_restock), product_id order by quantity asc, id asc) quantity_bucket, lead(quantity, 1) over (partition by product_id, store_id order by quantity asc, id asc) next_quantity from cleaned where store_id in (3, 4)), base as (select id, store_id, quantity, last_restock, quantity_tier, row_seq, quantity_bucket, next_quantity, row_seq * quantity row_seq_times_quantity, datediff(current_date(), last_restock) / 30 months_since_last_restock from with_windows where last_restock > date '2023-06-19' and row_seq > 8), matched_keys as (select id, store_id from base intersect all select id, store_id from inventory where store_id in (3, 4, 5, 6)), kept_rows as (select s.* from base s inner join matched_keys k on s.id = k.id and s.store_id = k.store_id) select date_trunc('month', last_restock) as activity_month, date_trunc('year', last_restock) as year_start, count(distinct store_id) as distinct_store_ids, count(*) as cnt from kept_rows group by date_trunc('month', last_restock), date_trunc('year', last_restock)
